// DeleteTeam is the resolver for the deleteTeam field.
func (r *mutationResolver) DeleteTeam(ctx context.Context, id string) (bool, error) {
	// Get authenticated user ID from context
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return false, fmt.Errorf("user not authenticated")
	}

	// Check authorization - admins, superadmins, and church admins (for teams created by their church members)
	if !r.RoleService.CanDeleteTeamByID(ctx, userID, id) {
		return false, fmt.Errorf("unauthorized to delete this team")
	}

	// Load the team to verify it exists and get its details
	teamThunk := r.Loaders.TeamByIDLoader.Load(ctx, id)
	team, err := teamThunk()
	if err != nil {
		return false, fmt.Errorf("failed to load team: %w", err)
	}

	// Get all team members before deletion
	members, err := r.DB.Queries.GetUsersByTeamIDs(ctx, []string{id})
	if err != nil {
		return false, fmt.Errorf("failed to get team members: %w", err)
	}

	// Delete the team
	err = r.DB.Queries.DeleteTeam(ctx, id)
	if err != nil {
		return false, fmt.Errorf("failed to delete team: %w", err)
	}

	// Invalidate team cache
	r.Cache.InvalidateTeam(id)

	// Invalidate project cache (for project.teams)
	r.Cache.InvalidateProject(team.ProjectID)

	// Invalidate superteam cache if team belonged to a superteam
	if team.SuperTeamID != nil {
		r.Cache.InvalidateSuperTeam(*team.SuperTeamID)
	}

	// Invalidate user caches for all team members
	for _, member := range members {
		r.Cache.InvalidateUser(member.ID)
	}

	// Invalidate teams filter queries
	r.Cache.DeletePrefix(cache.PrefixTeamsFilter)
	r.Cache.DeletePrefix(cache.PrefixTeamsCount)

	// Invalidate superteams filter queries (member counts may have changed)
	r.Cache.DeletePrefix(cache.PrefixSuperTeamsFilter)
	r.Cache.DeletePrefix(cache.PrefixSuperTeamsCount)

	return true, nil
}

// AddTeamMembers is the resolver for the addTeamMembers field.
func (r *mutationResolver) AddTeamMembers(ctx context.Context, teamID string, userIds []string, force *bool) (*model.Team, error) {
	// Get authenticated user ID from context
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Check authorization
	if !r.RoleService.CanManageTeam(ctx, userID, teamID) {
		return nil, fmt.Errorf("unauthorized to manage this team")
	}

	// Load team to verify it exists
	teamThunk := r.Loaders.TeamByIDLoader.Load(ctx, teamID)
	team, err := teamThunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load team: %w", err)
	}

	// Get team's project ID
	projectID, err := r.DB.Queries.GetTeamProjectID(ctx, teamID)
	if err != nil {
		return nil, fmt.Errorf("failed to get team project ID: %w", err)
	}

	// Determine whether to force add
	shouldForce := force != nil && *force

	// Add each user to the team
	for _, uid := range userIds {
		// Verify user exists (will be handled by loader)
		userThunk := r.Loaders.UserByIDLoader.Load(ctx, uid)
		_, err := userThunk()
		if err != nil {
			return nil, fmt.Errorf("failed to load user %s: %w", uid, err)
		}

		// Ensure user is enrolled in the project (auto-join if not already)
		isInProject, err := r.DB.Queries.IsUserInProject(ctx, sqlc.IsUserInProjectParams{
			Userid:    uid,
			Projectid: projectID,
		})
		if err != nil {
			return nil, fmt.Errorf("failed to check if user %s is in project: %w", uid, err)
		}
		if !isInProject {
			// Automatically join the user to the project
			err = r.DB.Queries.JoinProject(ctx, sqlc.JoinProjectParams{
				Userid:    uid,
				Projectid: projectID,
			})
			if err != nil {
				return nil, fmt.Errorf("failed to join user %s to project: %w", uid, err)
			}
		}

		// If not forcing, check if user is already on another team in this project
		if !shouldForce {
			existingTeam, err := r.DB.Queries.GetUserTeamByProjectID(ctx, sqlc.GetUserTeamByProjectIDParams{
				Userid:    uid,
				Projectid: projectID,
			})
			// If err is nil, user is already on a team
			if err == nil && existingTeam.ID != teamID {
				return nil, fmt.Errorf("user %s is already on team %s in this project", uid, existingTeam.ID)
			}
			// Ignore error if it's a "no rows" error (user not on any team)
		}

		// If forcing, remove user from all teams in this project first
		if shouldForce {
			// Get the user's current team before removing (for cache invalidation)
			oldTeam, err := r.DB.Queries.GetUserTeamByProjectID(ctx, sqlc.GetUserTeamByProjectIDParams{
				Userid:    uid,
				Projectid: projectID,
			})
			var oldTeamID string
			if err == nil {
				oldTeamID = oldTeam.ID
			}

			err = r.DB.Queries.RemoveUserFromTeamsInProject(ctx, sqlc.RemoveUserFromTeamsInProjectParams{
				Userid:    uid,
				Projectid: projectID,
			})
			if err != nil {
				return nil, fmt.Errorf("failed to remove user %s from existing teams: %w", uid, err)
			}

			// Invalidate old team cache so UI reflects the removal
			if oldTeamID != "" {
				r.Cache.InvalidateTeam(oldTeamID)
			}
		}

		// Add user to the team
		err = r.DB.Queries.AddTeamMember(ctx, sqlc.AddTeamMemberParams{
			Teamid: teamID,
			Userid: uid,
		})
		if err != nil {
			return nil, fmt.Errorf("failed to add user %s to team: %w", uid, err)
		}

		// Invalidate user cache
		r.Cache.InvalidateUser(uid)
		// Invalidate user's teams cache (used by TeamsByUserLoader)
		r.Cache.Delete(cache.TeamsByUserKey(uid))
	}

	// Invalidate team cache
	r.Cache.InvalidateTeam(teamID)

	// Invalidate superteam cache if team belongs to a superteam (member count changes)
	if team.SuperTeamID != nil {
		r.Cache.InvalidateSuperTeam(*team.SuperTeamID)
	}

	// Invalidate teams filter queries (member count changes)
	r.Cache.DeletePrefix(cache.PrefixTeamsFilter)
	r.Cache.DeletePrefix(cache.PrefixTeamsCount)

	// Invalidate superteams filter queries (member counts may have changed)
	r.Cache.DeletePrefix(cache.PrefixSuperTeamsFilter)
	r.Cache.DeletePrefix(cache.PrefixSuperTeamsCount)

	// Invalidate users filter queries (user.teams changes)
	r.Cache.DeletePrefix(cache.PrefixUsersFilter)
	r.Cache.DeletePrefix(cache.PrefixUsersCount)

	// Recalculate leaderboard exclusion based on average age
	avgAge, err := r.DB.Queries.GetTeamAverageAge(ctx, teamID)
	if err == nil {
		shouldExclude := avgAge >= 36.0
		_, _ = r.DB.Queries.UpdateTeamLeaderboardExcluded(ctx, sqlc.UpdateTeamLeaderboardExcludedParams{
			ID:                  teamID,
			Leaderboardexcluded: shouldExclude,
		})
		// Invalidate caches after updating exclusion status
		r.Cache.InvalidateTeam(teamID)
		r.Cache.Delete(cache.TeamsByProjectKey(team.ProjectID))
		r.Cache.DeletePrefix(cache.PrefixLeaderboard)
	}

	// Reload team to get updated leaderboard_excluded status
	updatedTeam, err := r.DB.Queries.GetTeamsByIDs(ctx, []string{teamID})
	leaderboardExcluded := false
	if err == nil && len(updatedTeam) > 0 {
		leaderboardExcluded = updatedTeam[0].LeaderboardExcluded
	}

	// Return the team (loaders already returns model.Team)
	return &model.Team{
		ID:                  team.ID,
		Name:                team.Name,
		Description:         team.Description,
		JoinCode:            team.JoinCode,
		LeaderboardExcluded: leaderboardExcluded,
	}, nil
}

